    private int speed = 60;
    public int getSpeed() {
        return this.speed;
    }
}
class SportsCar extends VehicleBase {
    public int getBoostedSpeed() {
        return getSpeed() + 40;
    }
}
public class Main {
    public static void main(String[] args) {
        SportsCar car = new SportsCar();
        System.out.println(car.getBoostedSpeed());
    }
}
```

